export const emptyLifecycle = {
    bootstrap () {
        return Promise.resolve();
    },
    mount () {
        return Promise.resolve();
    },
    unmount () {
        return Promise.resolve();
    }
};
export function routeRegex(regex, location) {
    const result = regex.test(location.pathname.replace(window.getOpenmrsSpaBase(), ''));
    return result;
}
